import { EMOJI_SOURCE, TONEABLE_SOURCE } from "./emojiData";
import { insertTone, stripTone, type EmojiGroup } from "./emoji";

// The emoji panel's characters (about 1,800, Unicode 14 and older), loaded
// with the panel and not with the chat: lib/emojiData.ts is generated by
// scripts/gen-emoji.mjs.

const FE0F = /️/g;
const key = (c: string) => stripTone(c).replace(FE0F, "");

function parse(): EmojiGroup[] {
  return EMOJI_SOURCE.map(([id, label, icon, text]) => ({
    id,
    label,
    icon,
    items: text.split("\n").map((line) => {
      const space = line.indexOf(" ");
      const char = line.slice(0, space);
      const [name = "", words = ""] = line.slice(space + 1).split("|");
      return { char, name: name.trim(), words: words.trim() };
    }),
  }));
}

export const EMOJI_GROUPS: EmojiGroup[] = parse();

/** Every emoji as the list writes it, by its characters without selectors. */
const WRITTEN = new Map(
  EMOJI_GROUPS.flatMap((g) => g.items).map((i) => [key(i.char), i.char]),
);
const TONEABLE = new Set(TONEABLE_SOURCE.split(" ").map(key));

/** The name of an emoji, with or without a skin tone. */
export function nameOf(char: string): string | undefined {
  const written = WRITTEN.get(key(char));
  return EMOJI_GROUPS.flatMap((g) => g.items).find((i) => i.char === written)
    ?.name;
}

/** Whether an emoji takes a skin tone. */
export function takesTone(char: string): boolean {
  return TONEABLE.has(key(char));
}

/** The emoji in skin tone `tone` (1 to 5; 0 for the default), if it takes one. */
export function withTone(char: string, tone: number): string {
  const plain = WRITTEN.get(key(char)) ?? stripTone(char);
  if (!takesTone(char) || tone < 1 || tone > 5) return plain;
  return insertTone(plain, tone);
}

/** The emoji whose name or words contain every word typed. */
export function searchEmoji(query: string) {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (terms.length === 0) return [];
  const out = [];
  for (const g of EMOJI_GROUPS)
    for (const it of g.items) {
      const hay = `${it.name} ${it.words}`.toLowerCase();
      if (terms.every((t) => hay.includes(t))) out.push(it);
    }
  return out;
}
